/* All displayed results come from assets/results.js, exported by build_data.py. */
'use strict';
const D = window.RESEARCH_DATA;
const COLORS = {teal:'#168575',blue:'#6d8fae',coral:'#d18c6b',navy:'#233e5b',grid:'#e9eff5'};
const MODEL_NAMES = {'logistic_C0.1_none':'Logistic regression',random_forest_leaf20_none:'Random forest',hist_gradient_boosting_leaves31_none:'Gradient boosting'};
const FINAL = D.metrics.find(r=>r.selected_final_model).model;
const fmt = (x,n=0)=>x==null||!Number.isFinite(Number(x))?'—':Number(x).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
const pct = (x,n=1)=>x==null||!Number.isFinite(Number(x))?'—':`${fmt(x*100,n)}%`;
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',data:'M4 20V10m5 10V4m6 16v-7m5 7V7',inference:'M4 6h16M4 12h16M4 18h16M9 3v6M16 9v6M11 15v6',prediction:'m3 17 5-5 5 2 8-10M16 4h5v5',validation:'m12 3 8 4v6c0 4-8 8-8 8s-8-4-8-8V7zM8 12l3 3 5-6',reproduction:'M8 3h8v3h4v15H4V6h4zM8 3v5h8V3M8 13l2 2 5-5',info:'M12 8h.01M12 11v6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',check:'m5 12 4 4L19 6',loans:'M5 3h14v18H5zM8 8h8M8 12h8M8 16h4'};
const icon = name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.data}"/></svg>`;
const NAV=[['overview','Overview'],['data','Data & exploration'],['inference','Associations'],['prediction','Prediction'],['validation','Validation · Ivy'],['reproduction','Reproducibility'],['improvement','Model improvement']];
let state={page:'overview',eda:'grade',scenario:'primary',inferenceModel:'A',model:FINAL,curve:'roc',subgroup:'grade',rule:0,improvementRule:'maximum_validation_f1',improvementCurve:'pr',thresholdIndex:Math.round(D.thresholdCurve.length/3)};
const main=document.getElementById('main');
const source=(key,label='Download CSV')=>`<a class="source-link" href="assets/tables/${D.sources[key]}" download>${label}</a>`;
const notice=(text,warm=false)=>`<div class="notice ${warm?'warm':''}">${icon('info')}<div>${text}</div></div>`;
const heading=(eyebrow,title,text)=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div></div>`;
const stat=(label,value,note,featured=false,ico='data')=>`<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;
const panel=(title,subtitle,content,key='',foot='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${key?source(key):''}</div>${content}${foot?`<div class="chart-foot">${foot}</div>`:''}</section>`;
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
const control=(id,label,items,value)=>`<div class="control"><label for="${id}">${label}</label><select id="${id}">${options(items,value)}</select></div>`;
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map((h,i)=>`<th ${i?'class="num"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td ${i?'class="num"':''}>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function svgFrame(label,body,w=620,h=265){return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${body}</svg></div>`;}
function lineChart(series,{label='',percent=true,max=1,min=0,xlabels=[],baseline=null,width=620,height=265}={}){
 const w=width,h=height,p={l:47,r:17,t:14,b:38},cw=w-p.l-p.r,ch=h-p.t-p.b;
 const X=x=>p.l+x*cw,Y=y=>p.t+(1-(y-min)/(max-min))*ch;
 let body='';
 for(let i=0;i<=4;i++){let v=min+(max-min)*i/4;body+=`<line class="grid-line" x1="${p.l}" x2="${w-p.r}" y1="${Y(v)}" y2="${Y(v)}"/><text class="axis-label" x="${p.l-9}" y="${Y(v)+4}" text-anchor="end">${percent?pct(v,0):fmt(v,2)}</text>`;}
 if(baseline!==null)body+=`<path d="M${X(0)} ${Y(baseline)}H${X(1)}" stroke="#a3afbc" stroke-dasharray="5 5" fill="none"/>`;
 for(const s of series){
  const points=s.points.filter(v=>Number.isFinite(v[0])&&Number.isFinite(v[1]));
  const path=points.map(([x,y],i)=>`${i?'L':'M'}${X(x).toFixed(2)},${Y(y).toFixed(2)}`).join(' ');
  if(s.area&&points.length)body+=`<path d="${path}L${X(points.at(-1)[0])},${Y(min)}L${X(points[0][0])},${Y(min)}Z" fill="${s.color}" opacity=".065"/>`;
  body+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="${s.dashed?1.5:2.8}" ${s.dashed?'stroke-dasharray="6 5"':''} stroke-linecap="round" stroke-linejoin="round"/>`;
  if(s.interactive!==false)points.forEach(([x,y],i)=>{if(points.length>55&&i%5!==0&&i!==points.length-1)return;const tip=s.tips?.[i]||`${s.name}\n${pct(y,2)}`;body+=`<circle cx="${X(x)}" cy="${Y(y)}" r="${points.length<15?4:3}" fill="${s.color}" opacity="${points.length<15?1:.01}" data-tip="${esc(tip)}" tabindex="0" aria-label="${esc(tip)}"/>`;});
 }
 if(xlabels.length)xlabels.forEach(([x,t])=>body+=`<text class="axis-label" x="${X(x)}" y="${h-8}" text-anchor="middle">${esc(t)}</text>`);
 else for(let i=0;i<=4;i++)body+=`<text class="axis-label" x="${X(i/4)}" y="${h-8}" text-anchor="middle">${pct(i/4,0)}</text>`;
 return svgFrame(label,body,w,h);
}
function bars(rows,{label='',labelKey='grade',rateKey='default_rate',countKey='loan_count',horizontal=false,max=null,rateLabel='Default rate',countLabel='Loans'}={}){
 if(horizontal){
  const h=Math.max(225,rows.length*36+25),w=620,l=167,r=58,t=6,range=max||Math.max(...rows.map(d=>d[rateKey]))*1.15;
  let body='';
  rows.forEach((d,i)=>{const y=t+i*36,v=d[rateKey],bw=(v/range)*(w-l-r),tip=`${d[labelKey]}\n${rateLabel} ${pct(v,2)}\n${countLabel} ${fmt(d[countKey])}`;
   body+=`<text class="chart-label" x="${l-12}" y="${y+20}" text-anchor="end">${esc(String(d[labelKey]).replaceAll('_',' '))}</text><rect x="${l}" y="${y+5}" width="${w-l-r}" height="20" rx="3" fill="#f0f5f8"/><rect x="${l}" y="${y+5}" width="${bw}" height="20" rx="3" fill="${COLORS.teal}" opacity=".85" data-tip="${esc(tip)}" tabindex="0" aria-label="${esc(tip)}"/><text class="chart-label" x="${l+bw+8}" y="${y+20}">${pct(v,1)}</text>`;
  });return svgFrame(label,body,w,h);
 }
 const w=580,h=265,l=44,r=13,t=15,b=37,cw=w-l-r,ch=h-t-b,range=max||Math.ceil(Math.max(...rows.map(d=>d[rateKey]))*10)/10||.1;
 let body='';
 for(let i=0;i<=4;i++){const y=t+ch-i*ch/4;body+=`<line class="grid-line" x1="${l}" x2="${w-r}" y1="${y}" y2="${y}"/><text class="axis-label" x="${l-8}" y="${y+4}" text-anchor="end">${pct(range*i/4,0)}</text>`;}
 rows.forEach((d,i)=>{const gap=cw/rows.length,bw=gap*.58,x=l+i*gap+(gap-bw)/2,v=d[rateKey],bh=v/range*ch,tip=`${d[labelKey]}\n${rateLabel} ${pct(v,2)}\n${countLabel} ${fmt(d[countKey])}`;body+=`<rect x="${x}" y="${t+ch-bh}" width="${bw}" height="${bh}" rx="4" fill="${i===rows.length-1?COLORS.coral:COLORS.teal}" opacity="${.65+i/rows.length*.3}" data-tip="${esc(tip)}" tabindex="0" aria-label="${esc(tip)}"/><text class="axis-label" x="${x+bw/2}" y="${h-12}" text-anchor="middle">${esc(d[labelKey])}</text>`;});
 return svgFrame(label,body,w,h);
}
function vintageChart(){const rows=D.vintage;return lineChart([{name:'Observed default',color:COLORS.teal,area:true,points:rows.map((r,i)=>[i/(rows.length-1),r.default_rate]),tips:rows.map(r=>`${r.issue_quarter}\nDefault rate ${pct(r.default_rate,2)}\nLoans ${fmt(r.loan_count)}`)}],{label:'Observed default rate by issue quarter, resolved loans only',max:.35,xlabels:[[0,'2007'],[.25,'2010'],[.5,'2013'],[.75,'2016'],[1,'2018']]});}
function overview(){const a=D.cleaning.actual,m=D.metrics.find(r=>r.model===FINAL);
 return `<section class="hero"><div><div class="eyebrow">LENDING CLUB · LOAN DEFAULT STUDY</div><h1>A clearer view<br>of loan default.</h1><p>Explore the borrower characteristics, predictive models, and validation behind 1.35 million resolved loans.</p><div class="tag">${icon('check')}Application-time predictors · Out-of-time evaluation</div></div><div class="hero-chart"><div class="hero-chart-label"><span>Observed default by issue quarter</span><span>2007–2018</span></div>${vintageChart().replace('class="chart"','class="hero-mini"')}<div class="hero-chart-label"><span>Resolved outcomes only</span><span>Unequal follow-up</span></div></div></section>
 <div class="stats">${stat('Resolved loans',fmt(a.final_row_count),'From 2.26 million accepted-loan records',true,'loans')}${stat('Observed default rate',pct(a.default_rate,2),'269,360 charged-off or default loans')}${stat('Test ROC-AUC',fmt(m.roc_auc,3),`${fmt(m.roc_auc_ci_low,3)}–${fmt(m.roc_auc_ci_high,3)} · 95% bootstrap CI`,'','prediction')}${stat('Held-out test loans',fmt(m.n_obs),'2018 origination cohort','','validation')}</div>
 ${D.improvement?notice('<strong>New exploratory comparison.</strong> An expanded model reaches ROC-AUC '+fmt(D.improvement.metrics[0].roc_auc,3)+'. <a href="#improvement">Explore the improvement study</a>. Original primary results below are retained for comparison.'):''}<div class="section-heading"><h2>The risk landscape</h2><p>Descriptive patterns across the resolved cohort</p></div>
 <div class="grid">${panel('Default over time','Issue quarter · observed default rate',vintageChart(),'vintage','Recent vintages have unequal follow-up. The fall in 2018 is not evidence that underlying credit risk improved.')}${panel('A clear gradient by grade','Loan grade · observed default rate',bars(D.grade,{label:'Default rates by Lending Club grade'}),'grade','Grade is assigned by Lending Club and summarizes its assessment of borrower risk.')}</div>
 <div class="section-heading"><h2>What the analysis tells us</h2><a class="source-link" href="#validation">Explore Ivy’s validation</a></div>
 <div class="insight-grid"><article class="insight"><div class="mini-label">ASSOCIATION</div><h3>Creditworthiness matters</h3><p>Higher FICO and income are associated with lower adjusted default odds. Longer terms and greater debt burdens are associated with higher odds.</p></article><article class="insight"><div class="mini-label">PREDICTION</div><h3>Useful, moderate discrimination</h3><p>Gradient boosting reaches ${fmt(m.roc_auc,3)} ROC-AUC. Its ROC-AUC improvement over random forest is small and uncertain.</p></article><article class="insight"><div class="mini-label">VALIDATION · IVY</div><h3>Ranking is only part of the story</h3><p>The selected model predicts ${pct(m.mean_predicted_prob,2)} average risk versus ${pct(m.observed_default_rate,2)} observed default. Calibration changes across vintages.</p></article></div>
 ${notice('<strong>Read the cohort correctly.</strong> Findings describe accepted loans with resolved outcomes. They do not represent rejected applicants or all loans issued in a year, and adjusted associations do not establish causation.')}`;
}
function eda(){const items=[['grade','Loan grade'],['fico','FICO score'],['interest','Interest rate'],['income','Annual income'],['purpose','Loan purpose']];const rows=D[state.eda],key=state.eda==='grade'?'grade':state.eda==='purpose'?'purpose':'group';const horizontal=state.eda!=='grade';
 const sorted=state.eda==='purpose'?[...rows].sort((a,b)=>b.default_rate-a.default_rate):rows;
 const missing=D.missingness.filter(r=>!r.column.endsWith('_was_missing')&&r.missing_count>0).sort((a,b)=>b.missing_proportion-a.missing_proportion).slice(0,7).map(r=>({...r,label:({'mths_since_last_record':'Last public record date','mths_since_last_delinq':'Last delinquency date','emp_length_years':'Employment length','revol_util':'Revolving utilization','dti':'Debt-to-income ratio','credit_history_months':'Credit history','annual_inc':'Annual income'})[r.column]||r.column}));
 const a=D.cleaning.actual;
 return heading('DATA & EXPLORATION','Start with the data.','Describe the cohort, inspect missingness, and explore default patterns before adjusting for other characteristics.')+
 `<div class="stats">${stat('Raw records',fmt(a.raw_row_count),'Frozen accepted-loan input',true)}${stat('Resolved cohort',fmt(a.final_row_count),`${pct(a.final_row_count/a.raw_row_count,1)} of raw records`)}${stat('Excluded outcomes',fmt(a.status_exclusions.total),'Unresolved or unknown statuses')}${stat('Issue-date coverage','2007–2018','June 2007 through December 2018')}</div>
 <div class="control-row">${control('eda-control','Explore a characteristic',items,state.eda)}</div>
 <div class="grid equal">${panel(`Default by ${items.find(i=>i[0]===state.eda)[1].toLowerCase()}`,'Descriptive associations · hover or focus for sample sizes',bars(sorted,{label:`Default rate by ${state.eda}`,labelKey:key,horizontal}),state.eda,'Every group is shown, including small samples. Bin labels retain the original CSV units; rates are descriptive.')}${panel('Group detail','Use group size alongside the observed default rate',table(['Group','Loans','Defaults','Default rate'],sorted.map(r=>[esc(r[key]).replaceAll('_',' '),fmt(r.loan_count),fmt(r.default_count),pct(r.default_rate,2)])),state.eda)}</div>
 <div class="grid equal">${panel('Where values are missing','Original fields · proportion missing',bars(missing,{label:'Missingness by original field',labelKey:'label',rateKey:'missing_proportion',countKey:'missing_count',horizontal:true,rateLabel:'Missing',countLabel:'Missing observations'}),'missingness','For these bars, hover counts refer to missing observations. Missing employment is retained with an indicator; structurally missing credit-event dates are excluded from primary continuous predictors.')}${panel('Cleaning decisions','A consistent target and auditable cohort',`<div class="label-value"><span>Fully Paid</span><strong>Outcome 0</strong></div><div class="label-value"><span>Charged Off / Default</span><strong>Outcome 1</strong></div><div class="label-value"><span>Current, late, grace or unknown</span><strong>Excluded</strong></div><div class="label-value"><span>Duplicate rows removed</span><strong>${fmt(a.duplicates.exact_rows_removed+a.duplicates.duplicate_id_rows_removed)}</strong></div><div class="label-value"><span>Post-outcome predictors</span><strong>Excluded by allowlist</strong></div><div class="label-value"><span>Impossible numeric values</span><strong>Set to missing</strong></div><div class="label-value"><span>Legitimate extreme observations</span><strong>Retained in cleaned data</strong></div><p class="footnote">Predictive imputers, percentile caps, scalers and encoders learn from training loans only. The inference models use their separately specified analysis cohorts.</p>`)}</div>`+
 notice('<strong>Selection matters.</strong> A loan must have a resolved outcome to enter the cohort. Recently issued loans that resolve quickly may differ systematically from those still outstanding.');
}
const FEATURE_LABELS={fico_per_10:'FICO · +10 points',log2_annual_inc:'Annual income · doubling',log2_loan_to_annual_income:'Loan/income · +1 log₂ unit',dti_per_10:'DTI · +10 percentage points',revol_util_per_10:'Utilization · +10 points',credit_history_years:'Credit history · +1 year',emp_length_years:'Employment · +1 year',delinq_2yrs:'Delinquencies · +1 event',inq_last_6mths:'Inquiries · +1 inquiry',open_acc_per_5:'Open accounts · +5',pub_rec:'Public records · +1',int_rate_per_5:'Interest rate · +5 points'};
function featureLabel(r){if(FEATURE_LABELS[r.parameter])return FEATURE_LABELS[r.parameter];if(r.parameter.startsWith('C(grade,'))return 'Grade '+r.parameter.match(/\[T\.(.)\]/)?.[1]+' vs Grade A';if(r.parameter.includes('term_months'))return '60-month vs 36-month term';if(r.parameter.includes('small_business'))return 'Small business vs debt consolidation';if(r.parameter.includes('T.RENT'))return 'Rent vs mortgage';return r.parameter;}
function inference(){if(state.scenario!=='primary')state.inferenceModel='A';const rows=D.inference.filter(r=>r.scenario===state.scenario&&r.model===state.inferenceModel);const wanted=['fico_per_10','log2_annual_inc','dti_per_10','revol_util_per_10','credit_history_years','emp_length_years','inq_last_6mths'];let chosen=rows.filter(r=>wanted.includes(r.parameter)||r.parameter.includes('term_months')||r.parameter.includes('small_business')||r.parameter.includes('T.RENT')||r.parameter==='int_rate_per_5'||r.parameter.startsWith('C(grade,'));
 const sample=D.inferenceSamples.find(r=>r.scenario===state.scenario&&r.model===state.inferenceModel),x=v=>Math.log(v/.6)/Math.log(6.5/.6)*300;
 let forest=`<div class="forest-header"><span>Adjusted characteristic</span><span>Odds ratio · 95% HC3 CI</span></div>`;
 forest+=chosen.map(r=>`<div class="forest-row"><span>${esc(featureLabel(r))}</span><svg viewBox="0 0 300 35" role="img" aria-label="${esc(featureLabel(r))}: odds ratio ${fmt(r.odds_ratio,3)}, 95 percent CI ${fmt(r.or_ci_low,3)} to ${fmt(r.or_ci_high,3)}"><line x1="${x(1)}" x2="${x(1)}" y1="0" y2="35" stroke="#b9c7d4" stroke-dasharray="3 3"/><line x1="${x(r.or_ci_low)}" x2="${x(r.or_ci_high)}" y1="17" y2="17" stroke="${r.odds_ratio<1?COLORS.teal:COLORS.coral}" stroke-width="3"/><circle cx="${x(r.odds_ratio)}" cy="17" r="4.5" fill="${r.odds_ratio<1?COLORS.teal:COLORS.coral}"/></svg><span class="forest-value">${fmt(r.odds_ratio,3)}<br><span>${fmt(r.or_ci_low,3)}–${fmt(r.or_ci_high,3)}</span></span></div>`).join('');forest+=`<div class="forest-row"><span>Odds ratio (log scale)</span><svg viewBox="0 0 300 35" aria-hidden="true">${[.6,1,2,5].map(v=>`<text x="${x(v)}" y="22" class="axis-label" text-anchor="${v===.6?'start':'middle'}">${v}</text>`).join('')}</svg><span></span></div>`;
 const modelText={A:'Borrower and application characteristics, plus issue-year controls; no grade or interest-rate proxy.',B:'Model A plus loan grade. Grade A is the reference category.',C:'Model A plus interest rate, replacing grade. Interest rate is measured per five percentage points.'};
 return heading('STATISTICAL INFERENCE','What is associated with default?','Adjusted odds ratios separate a characteristic’s association from the other terms included in the model.')+
 `<div class="control-row">${control('scenario-control','Analysis cohort / sensitivity',[['primary','Primary specification'],['mature','Maturity sensitivity'],['unwinsorized','Without winsorization'],['employment_complete_case','Employment complete cases']],state.scenario)}${control('inference-control','Adjusted model',state.scenario==='primary'?[['A','Model A · borrower characteristics'],['B','Model B · plus grade'],['C','Model C · plus interest rate']]:[['A','Model A · borrower characteristics']],state.inferenceModel)}</div>
 <div class="stats">${stat('Analysis loans',fmt(sample.nobs),'Inference cohort; differs from prediction',true)}${stat('Observed defaults',fmt(sample.default_count),pct(sample.default_rate,2)+' of analysis loans')}${stat('Covariance','HC3','Robust score-sandwich uncertainty')}${stat('Maximum VIF',fmt(sample.maximum_vif,2),'No severe collinearity indicated')}</div>
 <div class="grid forest-layout">${panel('Adjusted associations','Log scale · a ratio of 1 means no adjusted difference in odds',forest,'inference','Selected terms are shown. Download the full coefficient table for every category and missingness indicator.')}${panel('Read the model correctly',`Model ${state.inferenceModel}`,`<p class="footnote">${modelText[state.inferenceModel]}</p><div class="label-value"><span>Odds ratio below 1</span><strong class="accent">Lower adjusted odds</strong></div><div class="label-value"><span>Odds ratio above 1</span><strong>Higher adjusted odds</strong></div><div class="label-value"><span>Confidence interval includes 1</span><strong>Compatible with no odds difference</strong></div><div class="label-value"><span>Multiple comparisons</span><strong>BH false-discovery adjustment</strong></div><details open><summary>Why separate grade and interest rate?</summary><p>Both are assigned by the lender and encode its risk assessment. Separate models show how borrower associations change when conditioning on these summaries.</p></details><details><summary>Odds are different from probability</summary><p>An odds ratio of 0.90 means 10% lower adjusted odds for the stated increment. It does not mean a 10 percentage-point reduction in default probability.</p></details>`)}</div>
 ${notice('<strong>Association, not causation.</strong> Full-cohort inference estimates adjusted associations. It is separate from out-of-time prediction. Large sample sizes make small effects detectable; interpret effect sizes, uncertainty and sensitivity together.')}
 <p class="footnote">The maturity sensitivity uses contractual term completion by 2018-12-31. That endpoint is an analysis assumption; verify the documented outcome-observation date before interpreting follow-up.</p>`;
}
function modelTable(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Model</th><th class="num">Test ROC-AUC</th><th class="num">Test AP</th><th class="num">Brier score</th><th class="num">Validation log loss</th></tr></thead><tbody>${D.metrics.map(r=>{const c=D.modelComparison.find(m=>m.candidate_id===r.model);return `<tr class="${r.selected_final_model?'selected-row':''}"><td class="model-name">${MODEL_NAMES[r.model]}${r.selected_final_model?'<span class="badge">Selected</span>':''}</td><td class="num">${fmt(r.roc_auc,4)}<br><small>${fmt(r.roc_auc_ci_low,4)}–${fmt(r.roc_auc_ci_high,4)}</small></td><td class="num">${fmt(r.pr_auc_ap,4)}</td><td class="num">${fmt(r.brier_score,4)}</td><td class="num">${fmt(c.validation_log_loss,4)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function prediction(){const curve=state.curve,colors=[COLORS.blue,COLORS.coral,COLORS.teal];const curves=D.metrics.map((r,i)=>({name:MODEL_NAMES[r.model],color:colors[i],points:D.curves[r.model][curve],interactive:false}));if(curve==='roc')curves.unshift({name:'Random ranking',color:'#a9b4bf',points:[[0,0],[1,1]],dashed:true,interactive:false});const selected=D.metrics.find(r=>r.model===state.model);
 return heading('PREDICTIVE MODELLING · PAVEL','Can earlier loans predict later ones?','Three model families, twelve prespecified candidates, one shared temporal evaluation design.')+
 `<div class="grid equal">${panel('Split by origination time','Preprocessing is fitted on training loans only',`<div class="pipeline">${D.split.map((r,i)=>`<div class="pipeline-item"><div class="pipeline-label">${['LEARN','CHOOSE','EVALUATE'][i]}</div><h3>${r.partition[0].toUpperCase()+r.partition.slice(1)}</h3><p>${['Before 2017','2017 loans','2018 loans'][i]}</p><strong>${fmt(r.rows)}</strong><p>${pct(r.default_rate,2)} default</p></div>`).join('')}</div>`,'split')}${panel('How the final model was chosen','Keep model selection separate from the final test',`<div class="label-value"><span>Candidate settings</span><strong>4 per model family</strong></div><div class="label-value"><span>Selection criterion</span><strong>Minimum validation log loss</strong></div><div class="label-value"><span>Final choice</span><strong>Gradient boosting · 31 leaves</strong></div><div class="label-value"><span>Class weighting</span><strong>Unweighted candidate selected</strong></div><p class="footnote">All candidates share the same features and cohorts. Grade and issue year are excluded from prediction; interest rate is included. Lower log loss and Brier scores are better.</p>`)}</div>
 <div class="grid equal">${panel('Discrimination on later loans','2018 test · 56,318 resolved loans',`<div class="control-row"><div class="segmented" aria-label="Discrimination curve"><button data-curve="roc" class="${curve==='roc'?'active':''}" aria-pressed="${curve==='roc'}">ROC curve</button><button data-curve="pr" class="${curve==='pr'?'active':''}" aria-pressed="${curve==='pr'}">Precision–recall</button></div></div>`+lineChart(curves,{label:curve==='roc'?'Test ROC curves by model. Horizontal axis false positive rate; vertical axis true positive rate.':'Test precision–recall curves by model. Horizontal axis recall; vertical axis precision.',baseline:curve==='pr'?selected.prevalence_baseline:null})+`<div class="legend"><span><i class="blue"></i>Logistic</span><span><i class="coral"></i>Random forest</span><span><i></i>Boosting</span></div>`,'metrics',curve==='roc'?'Horizontal: false positive rate. Vertical: true positive rate. The diagonal is random ranking.':'Horizontal: recall. Vertical: precision. The dashed prevalence reference is '+pct(selected.prevalence_baseline,2)+'. Curves are downsampled for display; metrics use all predictions.')}${panel('Compare the selected candidates','Intervals are 95% loan-level bootstrap intervals',modelTable(),'metrics','The final model is chosen by validation log loss, not the displayed test metrics. AP denotes average precision, the implementation used for PR-AUC.')}</div>
 <div class="insight-grid"><article class="insight"><div class="mini-label">INTERPRETATION</div><h3>ROC-AUC is a ranking measure</h3><p>AUC 0.704 means roughly a 70.4% chance of ranking a random defaulter above a random non-defaulter. It is not classification accuracy.</p></article><article class="insight"><div class="mini-label">PAIRED COMPARISON</div><h3>A small gain over random forest</h3><p>The boosting-minus-forest ROC-AUC difference is 0.0011, with 95% CI −0.0003 to 0.0026. There is no clear ROC-AUC advantage.</p></article><article class="insight"><div class="mini-label">PREVALENCE</div><h3>Average precision needs context</h3><p>Boosting AP is 0.2935 against a 0.1576 prevalence reference. AP varies with outcome prevalence, so comparisons across cohorts need care.</p></article></div>`;
}
function validation(){const metric=D.metrics.find(r=>r.model===state.model),rule=D.thresholds[state.rule],curve=D.thresholdCurve[state.thresholdIndex];const subgroup=D.subgroups.filter(r=>r.subgroup_variable===state.subgroup);
 const calibrationSeries=[{name:'Perfect calibration',color:'#a9b4bf',points:[[0,0],[.6,.6]],dashed:true,interactive:false},{name:'Gradient boosting',color:COLORS.teal,points:D.calibration.map(r=>[r.mean_predicted_prob/.6,r.observed_default_rate]),tips:D.calibration.map(r=>`Prediction decile ${r.bin}\nPredicted ${pct(r.mean_predicted_prob,2)}\nObserved ${pct(r.observed_default_rate,2)}\nLoans ${fmt(r.n_loans)}`)}];calibrationSeries[0].points=[[0,0],[1,.6]];
 const frozenRuleItems=D.thresholds.map((r,i)=>[String(i),r.operating_goal]);
 return heading('MODEL VALIDATION · IVY','How reliable are the predictions?','Inspect uncertainty, probability calibration, frozen decision rules and subgroup performance.')+
 `<div class="control-row">${control('model-control','Model summary',D.metrics.map(r=>[r.model,MODEL_NAMES[r.model]]),state.model)}</div>
 <div class="stats">${stat('Test ROC-AUC',fmt(metric.roc_auc,4),`95% CI ${fmt(metric.roc_auc_ci_low,4)}–${fmt(metric.roc_auc_ci_high,4)}`,true)}${stat('Average precision',fmt(metric.pr_auc_ap,4),`Prevalence reference ${fmt(metric.prevalence_baseline,4)}`)}${stat('Mean predicted risk',pct(metric.mean_predicted_prob,2),`Observed ${pct(metric.observed_default_rate,2)}`)}${stat('Calibration slope',fmt(metric.calibration_slope,3),'Ideal slope = 1; lower means more extreme scores')}</div>
 <div class="grid equal">${panel('Probability calibration','Selected gradient-boosting model · prediction deciles',lineChart(calibrationSeries,{label:'Selected boosting model calibration. Horizontal axis mean predicted default probability, vertical axis observed rate.',max:.6,xlabels:[[0,'0%'],[1/3,'20%'],[2/3,'40%'],[1,'60%']]})+`<div class="legend"><span><i></i>Gradient boosting</span><span>Dashed: perfect calibration</span></div>`,'calibration','Horizontal: mean predicted probability. Vertical: observed default rate. This chart always shows the selected boosting model; the model selector above updates the summary cards.')}${panel('What the calibration says','Different from ranking quality',`<div class="label-value"><span>Selected model’s predicted risk</span><strong>19.19%</strong></div><div class="label-value"><span>Observed test default rate</span><strong>15.76%</strong></div><div class="label-value"><span>Calibration-in-the-large</span><strong>−0.268 · ideal 0</strong></div><div class="label-value"><span>Calibration slope</span><strong>0.828 · ideal 1</strong></div><p class="footnote">The model overpredicts risk on this resolved 2018 cohort. The maturity sensitivity changes the direction of calibration error, so this gap cannot be attributed to incomplete follow-up alone.</p><details><summary>How uncertainty was estimated</summary><p>Ivy uses seeded, nonparametric loan-level percentile bootstrap intervals: 1,000 resamples for overall metrics and paired comparisons, and 500 for secondary analyses. Intervals are conditional on the fitted model and assume independent loans.</p></details>`)}</div>
 <div class="section-heading"><div><h2>From probabilities to decisions</h2><p>Threshold choices use 2017 validation predictions, then remain frozen for 2018 testing.</p></div></div>
 <div class="control-row">${control('rule-control','Frozen operating rule',frozenRuleItems,String(state.rule))}</div>
 <div class="grid equal">${panel('Untouched-test decision results','Selected boosting model · frozen rule',`<div class="label-value"><span>Rule</span><strong>${esc(rule.operating_goal)}</strong></div><div class="label-value"><span>Threshold</span><strong>${rule.threshold==null?'No model threshold':fmt(rule.threshold,3)}</strong></div><div class="confusion"><div></div><div class="label">Predicted paid</div><div class="label">Predicted default</div><div class="label">Observed paid</div><div class="cell hit"><strong>${fmt(rule.tn)}</strong><span>True negatives</span></div><div class="cell error"><strong>${fmt(rule.fp)}</strong><span>False positives</span></div><div class="label">Observed default</div><div class="cell error"><strong>${fmt(rule.fn)}</strong><span>False negatives</span></div><div class="cell hit"><strong>${fmt(rule.tp)}</strong><span>True positives</span></div></div><div class="label-value"><span>Precision / recall</span><strong>${pct(rule.precision,1)} / ${pct(rule.recall,1)}</strong></div><div class="label-value"><span>Approval rate / relative cost per loan</span><strong>${pct(rule.approval_rate,1)} / ${fmt(rule.expected_cost,3)}</strong></div>`,'thresholds','Costs are illustrative: false negative costs 5 units and false positive 1. “Approval closest to 80%” targets validation approval; the test rate can differ.')}${panel('Explore the validation trade-off','2017 validation only · illustrative threshold',`<div class="range-wrap"><label class="sr-only" for="threshold-range">Validation threshold</label><input type="range" id="threshold-range" min="0" max="${D.thresholdCurve.length-1}" value="${state.thresholdIndex}" step="1" aria-valuetext="Threshold ${fmt(curve.threshold,3)}"><output class="range-number" id="threshold-value">${fmt(curve.threshold,3)}</output></div><div id="threshold-summary">${thresholdSummary(curve)}</div><p class="footnote">Move the slider to see how validation precision, recall and approval change. This exploration does not change the frozen rules or their reported test performance.</p>`,'thresholdCurve') }</div>
 <div class="section-heading"><div><h2>Performance across groups</h2><p>Selected boosting model · held-out test cohort</p></div>${control('subgroup-control','Group by',[...new Set(D.subgroups.map(r=>r.subgroup_variable))].map(v=>[v,v.replaceAll('_',' ')]),state.subgroup)}</div>
 ${panel('Subgroup detail','At least 200 loans and 30 observations in each outcome class are required for metrics.',table(['Group','Loans','Observed','Predicted','ROC-AUC · 95% CI'],subgroup.map(r=>[esc(r.subgroup_level),fmt(r.sample_size),pct(r.observed_default_rate,1),pct(r.mean_predicted_prob,1),r.adequate_sample?`${fmt(r.roc_auc,3)} <small>(${fmt(r.roc_auc_ci_low,3)}–${fmt(r.roc_auc_ci_high,3)})</small>`:'<span class="badge muted">Insufficient sample</span>'])),'subgroups')}
 <div class="spacer">${notice('<strong>Interpretation limits.</strong> Subgroup results are descriptive, not evidence of fairness or causal differences. Accepted-loan selection, unresolved outcomes, temporal drift and dependence between loans can affect performance and uncertainty.')}</div>
 <details><summary>Robustness analyses included by Ivy</summary><p>Alternative temporal split; interest rate neutralized at the training median; refitting on 36-month loans; and a contractual-maturity cohort. Class weighting and model-family comparisons are also retained from the prespecified validation comparison.</p><div class="download-list">${source('robustness','Download robustness results')}${source('paired','Download paired model comparisons')}</div></details>`;
}
function thresholdSummary(r){return `<div class="label-value"><span>Validation loans flagged</span><strong>${fmt(r.tp+r.fp)} / ${fmt(169321)}</strong></div><div class="label-value"><span>Precision</span><strong>${pct(r.precision,1)}</strong></div><div class="label-value"><span>Recall</span><strong>${pct(r.recall,1)}</strong></div><div class="label-value"><span>Approval rate</span><strong>${pct(r.approval_rate,1)}</strong></div><div class="label-value"><span>Illustrative relative cost / loan</span><strong>${fmt(r.expected_cost,3)}</strong></div>`;}
function reproduction(){const a=D.audit;return heading('REPRODUCIBILITY','Results you can trace.','A separate checkout and isolated environment regenerate the analysis from the frozen raw dataset.')+
 `<div class="stats">${stat('Synthetic tests',a.test_count==null?'Not recorded':fmt(a.test_count)+' passed','Cleaning, inference, modelling and validation',true,'check')}${stat('Reproduction checks',`${a.passed} / ${a.checks}`,'All recorded checks passed','','reproduction')}${stat('CSV comparisons','28 matched','27 regenerated tables + frozen feature contract')}${stat('Raw-data integrity','Unchanged','SHA-256 verified before and after')}</div>
 <div class="grid equal">${panel('One pipeline, distinct responsibilities','Every step contributes to the research question',`<div class="pipeline">${[['Cleaning audit','Validate cohort, parsing and leakage exclusions.'],['Exploration','Describe default patterns and missingness.'],['Inference','Estimate adjusted associations and uncertainty.'],['Prediction · Pavel','Compare models using temporal validation.'],['Validation · Ivy','Evaluate calibration, thresholds and robustness.'],['Reproduction','Rerun the workflow and compare outputs.']].map(([t,p])=>`<article class="pipeline-item"><h3>${t}</h3><p>${p}</p></article>`).join('')}</div>`)}${panel('Reproduction specification','Numerical equality with explicit tolerances',`<div class="label-value"><span>Counts, schema and categories</span><strong>Exact agreement</strong></div><div class="label-value"><span>CSV relative / absolute tolerance</span><strong>10⁻⁶ / 10⁻¹⁰</strong></div><div class="label-value"><span>Immediate EDA repeat</span><strong>Byte-identical outputs</strong></div><div class="label-value"><span>Predictor leakage checks</span><strong>Passed</strong></div><p class="footnote">${esc(a.scope)}</p><details><summary>Frozen dataset fingerprint</summary><div class="code">${esc(a.dataset_sha256)}</div></details><details><summary>Source provenance</summary><p>Analysis base commit:</p><div class="code">${esc(a.source_commit)}</div><p>The reproduction includes a recorded source overlay. This dashboard is a separate display of the resulting aggregate files.</p></details>`)}</div>
 ${panel('Inspect the checks','Filter by a filename, analysis stage or validation check.',`<label for="check-search" class="sr-only">Search reproducibility checks</label><input class="table-search" id="check-search" type="search" placeholder="Search checks, e.g. calibration or cleaning"><div id="checks-table">${checksTable(D.reproduction)}</div>`,'reproduction')}
 <div class="spacer">${notice('<strong>Reproducibility is not scientific validity.</strong> Matching results confirms consistent execution. Conclusions still depend on the cohort definition, outcome-observation date, modelling assumptions and interpretation.')}</div>
 <div class="download-list"><a class="button" href="assets/source-manifest.json" download>Source file fingerprints</a><a class="button" href="assets/results.json" download>Aggregate dashboard data</a></div><p class="footnote">AI assistance is disclosed in the project’s AI-use log. Member 5’s validation contribution is credited to Ivy.</p>`;}
function checksTable(rows){if(!rows.length)return '<p class="empty">No matching checks. Try another search.</p>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Check</th><th>Result</th><th>Detail</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.check).replaceAll('_',' ')}</td><td class="${r.passed?'checkmark':'failmark'}">${r.passed?'Passed':'Failed'}</td><td>${esc(r.detail)}</td></tr>`).join('')}</tbody></table></div>`;}
const pages={overview,data:eda,inference,prediction,validation,reproduction,improvement:()=>improvement()+xgboostSection()};
function render(){document.getElementById('navigation').innerHTML=NAV.map(([id,label])=>`<a class="nav-item ${state.page===id?'active':''}" href="#${id}" aria-label="${label}" title="${label}" ${state.page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-text">${label}</span></a>`).join('');document.getElementById('breadcrumb-current').textContent=NAV.find(n=>n[0]===state.page)[1];document.title=`${NAV.find(n=>n[0]===state.page)[1]} | Lending Club Research`;main.innerHTML=pages[state.page]();bind();}
function bind(){const binds={'eda-control':['eda'], 'scenario-control':['scenario'],'inference-control':['inferenceModel'],'model-control':['model'],'subgroup-control':['subgroup'],'rule-control':['rule',Number],'improvement-rule':['improvementRule']};Object.entries(binds).forEach(([id,[key,convert]])=>{const el=document.getElementById(id);if(el)el.onchange=()=>{state[key]=convert?convert(el.value):el.value;render();document.getElementById(id)?.focus();};});document.querySelectorAll('[data-curve]').forEach(b=>b.onclick=()=>{state.curve=b.dataset.curve;render();document.querySelector(`[data-curve="${state.curve}"]`).focus();});document.querySelectorAll('[data-improvement-curve]').forEach(b=>b.onclick=()=>{state.improvementCurve=b.dataset.improvementCurve;render();document.querySelector(`[data-improvement-curve="${state.improvementCurve}"]`).focus();});const search=document.getElementById('check-search');if(search)search.oninput=()=>{const q=search.value.toLowerCase();document.getElementById('checks-table').innerHTML=checksTable(D.reproduction.filter(r=>(r.check+' '+r.detail).toLowerCase().includes(q)));};const range=document.getElementById('threshold-range');if(range)range.oninput=()=>{state.thresholdIndex=Number(range.value);const r=D.thresholdCurve[state.thresholdIndex];document.getElementById('threshold-value').textContent=fmt(r.threshold,3);document.getElementById('threshold-summary').innerHTML=thresholdSummary(r);range.setAttribute('aria-valuetext',`Threshold ${fmt(r.threshold,3)}`);};}
function route(){const requested=location.hash.slice(1)||'overview';state.page=pages[requested]?requested:'overview';render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',route);
const tooltip=document.getElementById('tooltip');
function showTip(target,x,y){tooltip.textContent=target.dataset.tip;tooltip.style.display='block';const box=tooltip.getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(x+14,innerWidth-box.width-10))+'px';tooltip.style.top=Math.max(8,Math.min(y+14,innerHeight-box.height-10))+'px';}
document.addEventListener('pointermove',e=>{const target=e.target.closest('[data-tip]');if(target)showTip(target,e.clientX,e.clientY);else tooltip.style.display='none';});
document.addEventListener('focusin',e=>{const target=e.target.closest('[data-tip]');if(target){const r=target.getBoundingClientRect();showTip(target,r.left,r.bottom);}});document.addEventListener('focusout',()=>tooltip.style.display='none');
route();

document.addEventListener('keydown', e=>{if(e.key==='Escape')tooltip.style.display='none';});

function improvement(){
 const d=D.improvement;
 if(!d)return heading('EXPLORATORY FOLLOW-UP','Model improvement','Run the feature-extension workflow and rebuild the data bundle to display this comparison.');
 const before=d.comparison.find(r=>r.candidate==='original_baseline'),after=d.comparison.find(r=>r.candidate===d.candidate),m=d.metrics[0];
 const src=(key,label='Download CSV')=>`<a class="source-link" href="assets/tables/${d.sources[key]}" download>${label}</a>`;
 const ruleLabels={maximum_validation_f1:'Maximum validation F1',validation_cost_5_to_1:'Illustrative 5:1 cost rule'};
 const policy=d.policy.filter(r=>r.rule===state.improvementRule);
 const gains=d.paired.filter(r=>r.rule===state.improvementRule);
 const curve=state.improvementCurve;
 const series=[{name:'Original model',color:COLORS.blue,points:D.curves[FINAL][curve],interactive:false},{name:'Expanded grade model',color:COLORS.teal,points:d.curves[curve],interactive:false}];
 if(curve==='roc')series.unshift({name:'Random ranking',color:'#a9b4bf',points:[[0,0],[1,1]],dashed:true,interactive:false});
 const changes=[['ROC-AUC',before.roc_auc,after.roc_auc],['Average precision',before.pr_auc,after.pr_auc],['Brier score · lower is better',before.brier_score,after.brier_score],['Log loss · lower is better',before.log_loss,after.log_loss]];
 return heading('EXPLORATORY FOLLOW-UP','A stronger predictive candidate.','Additional reviewed application-time information improves risk ranking on the same resolved-loan cohort.')+
 notice('<strong>Exploratory test reuse.</strong> Candidates were chosen using 2016 average precision and thresholds using 2017. The 2018 cohort had already been examined in the original study, so this is not a fresh confirmatory test. The original primary results remain visible in the other sections.',true)+
 `<div class="stats spacer">${stat('Expanded model ROC-AUC',fmt(after.roc_auc,4),`Original ${fmt(before.roc_auc,4)} · same 56,318 loans`,true)}${stat('Expanded average precision',fmt(after.pr_auc,4),`${pct((after.pr_auc-before.pr_auc)/before.pr_auc,1)} relative gain`)}${stat('AP difference',`+${fmt(d.ap_delta,4)}`,`95% paired CI ${fmt(d.ap_delta_ci[0],4)}–${fmt(d.ap_delta_ci[1],4)}`)}${stat('Calibration slope',fmt(m.calibration_slope,3),'Original 0.828 · ideal 1')}</div>
 <div class="grid equal">${panel('Ranking improves','Selected candidate: expanded grade model',`<div class="control-row"><div class="segmented" aria-label="Improvement curve"><button data-improvement-curve="pr" class="${curve==='pr'?'active':''}">Precision–recall</button><button data-improvement-curve="roc" class="${curve==='roc'?'active':''}">ROC curve</button></div></div>`+lineChart(series,{label:curve==='pr'?'Original versus expanded model precision–recall curves; horizontal recall, vertical precision.':'Original versus expanded model ROC curves; horizontal false positive rate, vertical true positive rate.',baseline:curve==='pr'?after.default_rate:null})+`<div class="legend"><span><i class="blue"></i>Original</span><span><i></i>Expanded grade model</span></div><p class="footnote">${curve==='pr'?'Horizontal: recall. Vertical: precision. Dashed line: test default prevalence.':'Horizontal: false positive rate. Vertical: true positive rate.'} Curves are downsampled for display.</p>`)}${panel('Same-cohort numerical comparison','Higher ROC-AUC/AP; lower Brier score/log loss',table(['Metric','Original','Expanded'],changes.map(([label,b,a])=>[label,fmt(b,4),fmt(a,4)]))+`<div class="download-list">${src('comparison')}</div><p class="footnote">The average-precision difference is estimated with 1,000 paired loan bootstrap resamples, seed 5106. Intervals condition on fitted models and do not include model-search uncertainty.</p>`)}</div>
 <div class="section-heading"><div><h2>Precision and recall together</h2><p>Both models use thresholds selected on 2017, then frozen for 2018.</p></div>${control('improvement-rule','Operating rule',Object.entries(ruleLabels),state.improvementRule)}</div>
 ${panel('Frozen operating-point comparison',ruleLabels[state.improvementRule],table(['Model','Threshold','Precision','Recall','F1','False positives','Defaults found'],policy.map(r=>[r.candidate==='original_baseline'?'Original model':'Expanded grade model',fmt(r.threshold,3),pct(r.precision,2),pct(r.recall,2),fmt(r.f1,4),fmt(r.fp),fmt(r.tp)]))+`<div class="download-list">${src('policy')}</div><p class="footnote">A full set of observed validation-score thresholds is used for both models. This differs slightly from Ivy’s original 159-point grid. Test outcomes do not select the threshold. The cost rule assumes a false negative costs five times a false positive.</p>`)}
 <div class="grid equal spacer">${panel('Uncertainty in the gains','Expanded minus original · percentage-point differences',table(['Measure','Difference','95% paired CI'],gains.map(r=>[r.metric[0].toUpperCase()+r.metric.slice(1),`${r.delta>=0?'+':''}${fmt(r.delta*100,2)} pp`,`${fmt(r.ci_low*100,2)} to ${fmt(r.ci_high*100,2)} pp`]))+`<div class="download-list">${src('paired')}</div><p class="footnote">At maximum validation F1, the recall difference is uncertain. Precision and F1 gains have positive conditional intervals. High recall still comes with many false positives.</p>`)}${panel('What changed','A registered extension to the original predictors',`<div class="label-value"><span>Lender proxy</span><strong>Grade replaces interest rate</strong></div><div class="label-value"><span>Borrowing burden</span><strong>Loan amount and payment / income</strong></div><div class="label-value"><span>Credit-file information</span><strong>Balances and account composition</strong></div><div class="label-value"><span>History and geography</span><strong>Credit-event dates and application state</strong></div><p class="footnote">Thirteen specifications were tested across the feature-extension phases. The XGBoost comparison below uses six additional settings. The four expanded candidates were registered before fitting. The selected model uses 27 predictor columns; grade, subgrade and interest rate are never combined.</p>`)}</div>
 <div class="grid equal">${panel('Calibration remains imperfect','Diagnostic estimates; probabilities were not recalibrated on test',`<div class="label-value"><span>Mean predicted risk</span><strong>${pct(m.mean_predicted_prob,2)}</strong></div><div class="label-value"><span>Observed default</span><strong>${pct(m.observed_default_rate,2)}</strong></div><div class="label-value"><span>Calibration-in-the-large</span><strong>${fmt(m.calibration_intercept,3)} · ideal 0</strong></div><div class="label-value"><span>Calibration slope</span><strong>${fmt(m.calibration_slope,3)} · ideal 1</strong></div><p class="footnote">Risk remains overpredicted on average. Better ranking does not guarantee accurate probabilities or good decisions in a new vintage.</p>`)}${panel('Follow-up verification','Using Ivy’s unchanged validation utilities',`<div class="label-value"><span>Independent repeated fit</span><strong>Saved metrics reproduced</strong></div><div class="label-value"><span>Prediction identity / dates / outcomes</span><strong>56,318 loans verified</strong></div><div class="label-value"><span>Adequate subgroup strata</span><strong>${d.subgroups.filter(r=>r.adequate_sample).length} / ${d.subgroups.length}</strong></div><div class="label-value"><span>Additional temporal robustness</span><strong>Not performed for this extension</strong></div><div class="download-list">${src('metrics','Download validation metrics')}${src('subgroups','Download subgroup results')}</div><p class="footnote">The original Member 6 certificate covers the original pipeline. The extension has its own repeat-fit and identity checks; original robustness findings do not transfer automatically.</p>`)}</div>`;
}

function xgboostSection(){
 const d=D.xgboost;if(!d)return '';
 const a=d.comparison.find(r=>r.candidate==='expanded_grade_31'),b=d.comparison.find(r=>r.candidate===d.candidate);
 const src=(key,label='Download CSV')=>`<a class="source-link" href="assets/tables/${d.sources[key]}" download>${label}</a>`;
 const diff=d.paired.find(r=>r.metric==='f1');
 const dev=d.development.map(r=>[esc(r.candidate)+(r.candidate===d.candidate?'<span class="badge">Selected</span>':''),fmt(r.training_positive_weight,2),fmt(r.rounds),pct(r.precision,1),pct(r.recall,1),fmt(r.f1,4)]);
 const formatDelta=(metric,value)=>['precision','recall'].includes(metric)?`${fmt(value*100,2)} pp`:fmt(value,4);
 const changed=b.f1>a.f1?'higher':'lower';
 return `<div class="section-heading spacer"><div><div class="eyebrow">ADDITIONAL BENCHMARK · XGBOOST</div><h2>Does a different boosting algorithm help F1?</h2><p>Same 27 expanded grade predictors · six candidate settings · chronological development splits.</p></div></div>`+
 notice('<strong>Exploratory comparison.</strong> Candidate settings were selected by late-2016 F1 at thresholds learned on early-2016 loans. Final thresholds were selected on 2017, then frozen. The 2018 set remains a reused test cohort.')+
 `<div class="stats spacer">${stat('XGBoost test F1',fmt(b.f1,4),`Expanded model ${fmt(a.f1,4)} · ${changed} point estimate`,true)}${stat('XGBoost precision',pct(b.precision,2),`Expanded model ${pct(a.precision,2)}`)}${stat('XGBoost recall',pct(b.recall,2),`Expanded model ${pct(a.recall,2)}`)}${stat('Paired F1 difference',`${diff.delta>=0?'+':''}${fmt(diff.delta,4)}`,`95% CI ${fmt(diff.ci_low,4)} to ${fmt(diff.ci_high,4)}`)}</div>`+
 `<div class="grid equal">${panel('Frozen 2018 comparison','Both thresholds maximize F1 on 2017 validation',table(['Metric','Expanded model','XGBoost'],[['Precision',pct(a.precision,2),pct(b.precision,2)],['Recall',pct(a.recall,2),pct(b.recall,2)],['F1',fmt(a.f1,4),fmt(b.f1,4)],['Average precision',fmt(a.pr_auc,4),fmt(b.pr_auc,4)],['ROC-AUC',fmt(a.roc_auc,4),fmt(b.roc_auc,4)],['Brier score',fmt(a.brier_score,4),fmt(b.brier_score,4)],['False positives',fmt(a.fp),fmt(b.fp)],['Defaults found',fmt(a.tp),fmt(b.tp)]])+`<div class="download-list">${src('comparison')}</div>`)}${panel('Paired uncertainty','XGBoost minus expanded model · 1,000 loan resamples',table(['Measure','Difference','95% CI'],d.paired.map(r=>[r.metric.replaceAll('_',' '),formatDelta(r.metric,r.delta),`${formatDelta(r.metric,r.ci_low)} to ${formatDelta(r.metric,r.ci_high)}`]))+`<div class="download-list">${src('paired')}</div><p class="footnote">Intervals hold the fitted models and validation-selected thresholds fixed. They exclude training/search uncertainty. An interval spanning zero does not establish a clear gain.</p>`)}</div>`+
 panel('Development comparison','Thresholds: 2016 H1 · candidate evaluation: 2016 H2',table(['Candidate','Positive weight','Rounds','Precision','Recall','F1'],dev)+`<p class="footnote">Current expanded-model reference on this development split: F1 ${fmt(d.reference[0].f1,4)}. Development prevalence differs from 2018, so the absolute F1 values should not be compared across these cohorts.</p><div class="download-list">${src('development')}</div>`)+
 `<div class="grid equal spacer">${panel('Reproducible configuration',`XGBoost ${esc(d.version)}`,`<div class="label-value"><span>Selected setting</span><strong>${esc(d.candidate)}</strong></div><div class="label-value"><span>Boosting rounds</span><strong>${fmt(d.rounds)}</strong></div><div class="label-value"><span>Final positive-class weight</span><strong>${fmt(d.weight,3)}</strong></div><div class="label-value"><span>Saved-model reload</span><strong>${d.reload_matches?'Predictions matched':'Not verified'}</strong></div><p class="footnote">Early stopping uses late-2015 data entirely inside the development training period. Round count is frozen before candidate comparison and final refitting.</p>`)}${panel('Probability diagnostics','Model estimates were not recalibrated on test outcomes',`<div class="label-value"><span>Mean predicted risk</span><strong>${pct(d.calibration[0].mean_predicted_prob,2)}</strong></div><div class="label-value"><span>Observed default rate</span><strong>${pct(d.calibration[0].observed_default_rate,2)}</strong></div><div class="label-value"><span>Calibration-in-the-large</span><strong>${fmt(d.calibration[0].calibration_intercept,3)} · ideal 0</strong></div><div class="label-value"><span>Calibration slope</span><strong>${fmt(d.calibration[0].calibration_slope,3)} · ideal 1</strong></div><p class="footnote">Class weighting can affect probability calibration. A change in F1 should be assessed alongside ranking, calibration and false-positive costs.</p>`)}</div>`;
}
